import { DateTime } from "./src/luxon.js";
import { daysInMonth } from "./src/impl/util.js";

function refAddMonths(y, m, d, addM) {
  let total = (y * 12 + (m - 1)) + addM;
  let ny = Math.floor(total / 12);
  let nm = total % 12 + 1;
  let nd = Math.min(d, daysInMonth(ny, nm));
  return { y: ny, m: nm, d: nd };
}

let fails = 0;
for (const y of [96,97,98,99,100,101,102,103,104,1996,1999,2000,2001,2003,2004]) {
  for (let m = 1; m <= 12; m++) {
    for (const d of [1, 15, 28, 29, 30, 31]) {
      // skip invalid start dates
      if (d > daysInMonth(y, m)) continue;
      for (const add of [1,2,3,12,13,14,24,25,36]) {
        const dt = DateTime.utc(y, m, d).plus({ months: add });
        const r = refAddMonths(y, m, d, add);
        if (dt.year !== r.y || dt.month !== r.m || dt.day !== r.d) {
          if (fails < 40) console.log(`FAIL ${y}-${m}-${d} +${add}mo => got ${dt.year}-${dt.month}-${dt.day}, want ${r.y}-${r.m}-${r.d}`);
          fails++;
        }
      }
    }
  }
}
console.log("total month fails:", fails);
EOF
