import { DateTime } from "./src/luxon.js";
import { daysInMonth } from "./src/impl/util.js";

function refPlus(year, month, day, dur) {
  const y = year + (dur.years || 0);
  const m0 = month - 1 + (dur.months || 0) + (dur.quarters || 0) * 3;
  const ny = y + Math.floor(m0 / 12);
  const nm = ((m0 % 12) + 12) % 12 + 1;
  const nd = Math.min(day, daysInMonth(ny, nm)) + (dur.days || 0) + (dur.weeks || 0) * 7;
  const d = new Date(Date.UTC(2000, nm - 1, nd));
  d.setUTCFullYear(ny);
  return `${String(d.getUTCFullYear()).padStart(4, "0")}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`;
}

let fails = 0;
const years = [95,96,97,98,99,100,101,102,103,104,105,1899,1900,1901,1999,2000,2001,2099,2100,2101];
const durs = [];
for (let m = 1; m <= 14; m++) durs.push({ months: m });
for (let y = 1; y <= 3; y++) durs.push({ years: y });
for (let d = 1; d <= 400; d++) durs.push({ days: d });
for (const y of years) {
  for (let mo = 1; mo <= 12; mo++) {
    for (const day of [1, 15, 27, 28, 29, 30, 31]) {
      let dt;
      try { dt = DateTime.fromObject({ year: y, month: mo, day }); } catch (e) { continue; }
      if (!dt.isValid) continue;
      for (const dur of durs) {
        const got = dt.plus(dur).toISODate();
        const exp = refPlus(y, mo, day, dur);
        if (got !== exp) {
          if (fails < 40) console.log(`MISMATCH ${y}-${mo}-${day} + ${JSON.stringify(dur)}: got ${got} exp ${exp}`);
          fails++;
        }
      }
    }
  }
}
console.log("total mismatches:", fails);
